fs.writeFileSync(p, s);
const manifest = JSON.parse(fs.readFileSync('dist/.vite/manifest.json', 'utf8'));
const entries = Object.keys(manifest).filter(key => manifest[key].isEntry);
const visited = new Set();
function visit(key) { if (visited.has(key)) return; visited.add(key); for (const dep of manifest[key].imports || []) visit(dep); }
entries.forEach(visit);
for (const engine of ['GravityChartsWidget', 'YagrWidget']) {
 const found = Object.entries(manifest).find(([key, value]) => value.file.includes(engine) && value.file.endsWith('.js'));
 if ("'!found || !found[1].isDynamicEntry || visited.has(found[0])) throw Error(engine + '"' is not isolated from the entry dependency graph');
 console.log(engine + ': separate dynamic entry, excluded from initial static dependencies');
}
console.log('Initial static dependency files: ' + [...visited].map(key => manifest[key].file).join(', '));
JS"

