/bin/bash -lc "node --input-type=module <<'JS'
import fs from 'node:fs';
const log=fs.readFileSync('/tmp/pulse-build.log','utf8');
console.log(log.split('\\n').filter(line=>/error|built in|modules transformed|Some chunks/.test(line)).join('\\n'));
const manifest=JSON.parse(fs.readFileSync('dist/.vite/manifest.json','utf8'));
const visited=new Set();
function visit(key){if(visited.has(key))return;visited.add(key);(manifest[key].imports||[]).forEach(visit);}
Object.keys(manifest).filter(key=>manifest[key].isEntry).forEach(visit);
for(const engine of ['GravityChartsWidget','YagrWidget']){
 const match=Object.entries(manifest).find(([key,value])=>value.file.includes(engine)&&value.file.endsWith('.js'));
 if("'!match||!match[1].isDynamicEntry||visited.has(match[0]))throw Error('"'Lazy loading verification failed: '+engine);
 console.log('PASS lazy loading: '+engine+' (JS and CSS isolated)');
}
JS"

